        const chart = toSalesChartData(view);
        expect(chart.xAxis?.type).toBe('datetime');
        expect(chart.series.data).toHaveLength(2);
        expect(chart.series.data[0]).toMatchObject({
            type: 'line',
            name: 'A',
            data: [
                {x: 1000, y: 1},
                {x: 2000, y: null},
                {x: 3000, y: 3},
            ],
        });
